use fframes::{
    Scene, Video,
    animation::{Easing, KeyFramesAnimation},
    timeline,
};

use crate::PixelVideo;

#[derive(Debug)]
pub struct FinalScene {
    pub duration: f32,
    pub animation: KeyFramesAnimation<f32>,
}

impl FinalScene {
    pub fn new(duration: f32) -> Self {
        Self {
            duration,
            animation: timeline!(
                at 0.0 => duration, animate 3000.0 => 0.0, Easing::Linear
            ),
        }
    }
}

